# JS handling helpers
class JSUndefined:
    def __repr__(self):
        return "undefined"
    __str__ = __repr__

JS_UNDEFINED = JSUndefined()

class JSNull:
    def __repr__(self):
        return "null"
    __str__ = __repr__

JS_NULL = JSNull()

class JSObject(dict):
    def __getattr__(self, name):
        if name in self:
            v = self[name]
            return wrap_js(v)
        if name == "length":
            # for object, length is undefined
            return JS_UNDEFINED
        # Check for methods? For object, maybe not
        # Return undefined for missing
        return JS_UNDEFINED
    def __setattr__(self, name, value):
        if name.startswith("_"):
            super().__setattr__(name, value)
        else:
            self[name] = value
    def __getitem__(self, key):
        if isinstance(key, int):
            # object accessed by index? return undefined
            return JS_UNDEFINED
        return super().__getitem__(key) if key in self else JS_UNDEFINED

class JSArray(list):
    @property
    def length(self):
        return len(self)
    def map(self, fn):
        res = []
        for i, el in enumerate(self):
            try:
                r = fn(el, i, self)
            except TypeError:
                try:
                    r = fn(el)
                except TypeError:
                    r = fn(el, i)
            res.append(r)
        return JSArray(res)
    def filter(self, fn):
        res = []
        for i, el in enumerate(self):
            try:
                keep = fn(el, i, self)
            except TypeError:
                try:
                    keep = fn(el)
                except TypeError:
                    keep = fn(el, i)
            # JS truthiness
            if keep:
                res.append(el)
        return JSArray(res)
    def join(self, sep=","):
        # sep may be JSString
        if isinstance(sep, JSString):
            sep = str(sep)
        elif sep is None:
            sep = ","
        return JSString(sep.join(str(unwrap_js(x)) if not isinstance(x, JSUndefined) else "" for x in self))
    def slice(self, start=0, end=None):
        if end is None:
            return JSArray(self[start:])
        return JSArray(self[start:end])
    def __getattr__(self, name):
        # For array, allow length etc. Already property
        if name == "length":
            return len(self)
        raise AttributeError(name)

class JSString(str):
    @property
    def length(self):
        return len(self)
    def split(self, sep=None):
        if sep is None:
            return JSArray([JSString(s) for s in super().split()])
        if isinstance(sep, JSString):
            sep = str(sep)
        # JS split with string sep
        parts = super().split(sep)
        return JSArray([JSString(p) for p in parts])
    def toUpperCase(self):
        return JSString(self.upper())
    def toLowerCase(self):
        return JSString(self.lower())
    def toString(self):
        return JSString(self)
    def __getattr__(self, name):
        if name == "length":
            return len(self)
        raise AttributeError(name)

def wrap_js(v):
    if isinstance(v, JSObject) or isinstance(v, JSArray) or isinstance(v, JSString) or isinstance(v, JSUndefined) or v is None:
        return v
    if v is JS_UNDEFINED or v is JS_NULL:
        return v
    if isinstance(v, dict):
        o = JSObject()
        for k, val in v.items():
            o[k] = wrap_js(val)
        return o
    if isinstance(v, list):
        return JSArray([wrap_js(x) for x in v])
    if isinstance(v, str):
        return JSString(v)
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return v
    if v is None:
        return None
    return v

def unwrap_js(v):
    if isinstance(v, JSObject):
        return {k: unwrap_js(val) for k, val in v.items()}
    if isinstance(v, JSArray):
        return [unwrap_js(x) for x in v]
    if isinstance(v, JSString):
        return str(v)
    if isinstance(v, JSUndefined):
        return JS_UNDEFINED
    if isinstance(v, JSNull):
        return None
    if v is JS_UNDEFINED:
        return JS_UNDEFINED
    return v

# For environment
class _Object:
    @staticmethod
    def keys(o):
        if isinstance(o, (dict, JSObject)):
            return JSArray(list(o.keys()))
        # if o is JSArray? then keys are indices? In JS, Object.keys([1,2]) => ["0","1"]
        if isinstance(o, (list, JSArray)):
            return JSArray([str(i) for i in range(len(o))])
        if isinstance(o, JSUndefined) or o is None:
            raise TypeError("Cannot convert undefined or null to object")
        return JSArray([])
    @staticmethod
    def values(o):
        if isinstance(o, (dict, JSObject)):
            return JSArray(list(o.values()))
        if isinstance(o, (list, JSArray)):
            return JSArray(list(o))
        return JSArray([])
    @staticmethod
    def entries(o):
        if isinstance(o, (dict, JSObject)):
            return JSArray([[k, v] for k,v in o.items()])
        return JSArray([])

class _JSON:
    @staticmethod
    def stringify(o, *args, **kwargs):
        # unwrap and json dumps without pretty
        unwrapped = unwrap_js(o)
        # Handle undefined, function, etc. JSON.stringify(undefined) => undefined in JS? But in fx, JSON.stringify returns string
        # For fx, JSON.stringify applied to object returns JSON string.
        # We should return string
        try:
            s = json.dumps(unwrapped, ensure_ascii=False, separators=(',', ':'))
            return JSString(s)
        except:
            return JSString("null")
    @staticmethod
    def parse(s):
        if isinstance(s, JSString):
            s = str(s)
        data = json.loads(s)
        return wrap_js(data)

class _Math:
    @staticmethod
    def max(*args):
        # args may be JS values
        vals = [unwrap_js(a) for a in args]
        # If single array arg?
        if len(vals)==1 and isinstance(vals[0], list):
            vals = vals[0]
        try:
            return max(vals)
        except:
            return float('nan')
    @staticmethod
    def min(*args):
        vals = [unwrap_js(a) for a in args]
        if len(vals)==1 and isinstance(vals[0], list):
            vals = vals[0]
        try:
            return min(vals)
        except:
            return float('nan')

Object = _Object()
JSON = _JSON()
