                out.append(m)
        sys.stdout.write("\n".join(out))
        return True
    if file_arg is not None:
        if prefix=="" or prefix.startswith("."):
            try:
                with open(file_arg,'r',encoding='utf-8') as f:
                    content=f.read()
                data=json.loads(content)
            except:
                data=None
                try:
                    data=json.loads(content) if content.strip() else None
                except:
                    data=None
                if data is None:
                    # try to read as raw? But for completion, if json fails, we return empty
                    pass
            if isinstance(data, dict):
                if prefix=="":
                    parent_path=[]
                    leaf=""
                elif prefix==".":
                    parent_path=[]
                    leaf=""
                else:
                    remainder=prefix[1:]
                    split_parts=remainder.split(".")
                    if len(split_parts)==1:
                        parent_path=[]
                        leaf=split_parts[0]
                    else:
                        parent_path=split_parts[:-1]
                        leaf=split_parts[-1]
                cur=data
                for key in parent_path:
                    if isinstance(cur, dict) and key in cur:
                        cur=cur[key]
                    else:
                        cur=None
                        break
                out_lines=[]
                if isinstance(cur, dict):
                    for k in cur.keys():
