                                value="."+k
                            if is_zsh:
                                out_lines.append(f"{display}\t{value}\tkey")
                            else:
                                out_lines.append(value)
                sys.stdout.write("\n".join(out_lines))
                return True
        sys.stdout.write("")
        return True
    # file completion
    if prefix=="":
        dir_part="."
        base=""
    elif "/" in prefix:
        dir_part=os.path.dirname(prefix)
        base=os.path.basename(prefix)
        if dir_part=="":
            dir_part="/"
    else:
        dir_part="."
        base=prefix
    if dir_part=="":
        dir_part="."
    try:
        entries=os.listdir(dir_part if dir_part!="" else ".")
    except:
        entries=[]
    filtered=[e for e in entries if e.startswith(base)]
    filtered.sort()
    out_lines=[]
    for e in filtered:
