                    while j<len(s) and s[j] in " \t\n\r":
                        j+=1
                    if j<len(s) and s[j]==':':
                        res+=f'"{key}"'
                        continue
                    else:
                        res+=key
                        continue
                continue
            res+=c
            i+=1
        return res
    code_py = quote_keys(code_py)
    return code_py

def apply_js_code(data, code_str):
    original_code = code_str
    code_str = code_str.strip()
    if code_str=="":
        return data
    if code_str.startswith("."):
        code_str = "x => x" + code_str
    # Check if code is arrow or function
    # Arrow detection
    if "=>" in code_str:
        # Split at first =>
        parts = code_str.split("=>",1)
        left = parts[0].strip()
        right = parts[1].strip()
        # left could be "x", "(x)", "(x, y)", "x", "x => y => ..." nested?
        # For our cases, left is single param like "x", "(x)", "x", "(x)", "(y)"
        # Extract param name
        param = left.strip("() ").split(",")[0].strip()
        if not param:
            param = "x"
        body = right
        # Body could be "{...}" with return, or expression, or "({b: x.a})"
        if body.startswith("{") and body.endswith("}"):
            # Could be block or object literal
            # Distinguish: if body contains "return" then it's block
            if "return" in body:
                # block
                # Extract statements between { and }
                inner = body[1:-1].strip()
                # Translate body to python statements
                # Replace JS statements with python
                # For "y=2; return x.a+y" we need to handle
                # Simplify: translate inner
                py_body = js_translate_to_python(inner)
                # Now create function
                # We need to exec a function definition
                func_code = f"def _fn({param}):\n"
                # Split by ; or \n
                stmts = re.split(r'[;\n]', py_body)
                for stmt in stmts:
                    stmt=stmt.strip()
                    if not stmt:
                        continue
                    if stmt.startswith("return"):
                        expr = stmt[len("return"):].strip()
                        func_code += f"    return {expr}\n"
                    else:
                        func_code += f"    {stmt}\n"
                # If no return, return None (which will be undefined?)
                env = {"JS_UNDEFINED": JS_UNDEFINED, "Object": Object, "JSON": JSON, "Math": Math, "wrap_js": wrap_js, "unwrap_js": unwrap_js, "JSObject": JSObject, "JSArray": JSArray, "JSString": JSString}
                # Add data as x? No, function will be called with data
                try:
                    exec(func_code, env)
                    fn = env["_fn"]
                    # Call function with data
                    # Need to wrap data
                    wrapped = wrap_js(data) if not isinstance(data, (JSObject, JSArray, JSString, JSUndefined)) else data
                    # For function, `this` should be data as well, but we don't have this in arrow
                    result = fn(wrapped)
                    return result
                except Exception as e:
                    # Format error like original
                    # Need to print original_code with caret
                    sys.stderr.write(f"\n  {original_code}\n  {'^'*len(original_code)}\n\n{type(e).__name__}: {e}\n")
                    sys.exit(1)
            else:
                # object literal expression, e.g., "{ \"a\": 1 }" or "({b: x.a})" with parentheses?
                # If body is "{...}" without return, it's expression returning object?
                # But arrow "x=>{a:1}" would be ambiguous: JS treats "x=>{a:1}" as block with label, not object, so need parentheses "x=>({a:1})" to return object
                # Our detection: if body is "{a: 1}" without return, we should treat as block? Actually "x=>{a:1}" in JS without parentheses is block, not object, so returns undefined
                # We saw "x=>{a:1}" gave undefined? Let's see: we tested "x=>{a:1}" earlier gave undefined. Yes.
                # So "x=>{a:1}" should be treated as block with no return => undefined
                # While "x=>({b: x.a})" is object literal
                # How to distinguish? If body starts with "{" and ends with "}" and contains ":", and not contains "return", then it could be either block or object
                # For "x=>{a:1}", it's block with label a: (JS label) and expression 1, but not return, so undefined
                # For simplicity, if body is "{...}" and contains ":" and no "return", we will treat as undefined unless it's wrapped in parentheses
                # Since body for "x=>{a:1}" is "{a:1}" (no parens), we return undefined
                # For "x=>({b: x.a})", body is "({b: x.a})" with parens, we should unwrap parens and return object
                return JS_UNDEFINED
        else:
            # expression body
            # Remove surrounding parentheses for object literal case: "({b: x.a})" -> "{b: x.a}"
            if body.startswith("(") and body.endswith(")"):
                body = body[1:-1].strip()
            py_body = js_translate_to_python(body)
            # Create lambda
            env = {"JS_UNDEFINED": JS_UNDEFINED, "Object": Object, "JSON": JSON, "Math": Math, "wrap_js": wrap_js, "unwrap_js": unwrap_js, "JSObject": JSObject, "JSArray": JSArray, "JSString": JSString}
            # Define function via exec
            func_code = f"def _fn({param}):\n    return {py_body}\n"
            try:
                exec(func_code, env)
                fn = env["_fn"]
                wrapped = wrap_js(data) if not isinstance(data, (JSObject, JSArray, JSString, JSUndefined)) and data is not JS_UNDEFINED else data
                # Also need to handle `this` inside? Arrow doesn't have this, but we set this = data in env for eval?
                # For now, just call
                result = fn(wrapped)
                # Handle JSUndefined etc.
                return result
            except Exception as e:
                # Check if error is NameError for y not defined etc.
                sys.stderr.write(f"\n  {original_code}\n  {'^'*len(original_code)}\n\n{type(e).__name__}: {e}\n")
                sys.exit(1)
    elif code_str.startswith("function"):
        # function(x){return x.a;}
        m = re.match(r'function\s*\(\s*(\w+)\s*\)\s*\{(.+)\}', code_str, re.DOTALL)
        if m:
            param = m.group(1)
            body = m.group(2).strip()
            # body may contain return
            py_body = js_translate_to_python(body)
            func_code = f"def _fn({param}):\n"
            stmts = re.split(r'[;\n]', py_body)
            for stmt in stmts:
                stmt=stmt.strip()
                if not stmt:
                    continue
                if stmt.startswith("return"):
                    expr = stmt[len("return"):].strip().rstrip(";")
                    func_code += f"    return {expr}\n"
                else:
                    func_code += f"    {stmt}\n"
            env = {"JS_UNDEFINED": JS_UNDEFINED, "Object": Object, "JSON": JSON, "Math": Math}
            try:
                exec(func_code, env)
                fn = env["_fn"]
                wrapped = wrap_js(data) if not isinstance(data, (JSObject, JSArray, JSString, JSUndefined)) else data
                result = fn(wrapped)
                return result
            except Exception as e:
                sys.stderr.write(f"\n  {original_code}\n  {'^'*len(original_code)}\n\n{type(e).__name__}: {e}\n")
                sys.exit(1)
        else:
            sys.stderr.write(f"\n  {original_code}\n  {'^'*len(original_code)}\n\nSyntaxError: Unexpected token function\n")
            sys.exit(1)
    else:
        # expression
        # Could be "Object.keys", "1+1", "this", "x", "\"hello\"", "{a: 1}", etc.
        py_code = js_translate_to_python(code_str)
        env = {
            "JS_UNDEFINED": JS_UNDEFINED,
            "Object": Object,
            "JSON": JSON,
            "Math": Math,
            "x": wrap_js(data) if not isinstance(data, (JSObject, JSArray, JSString, JSUndefined)) and data is not JS_UNDEFINED else data,
            "this": wrap_js(data) if not isinstance(data, (JSObject, JSArray, JSString, JSUndefined)) and data is not JS_UNDEFINED else data,
            "wrap_js": wrap_js,
            "unwrap_js": unwrap_js,
            "JSObject": JSObject,
            "JSArray": JSArray,
            "JSString": JSString,
        }
        # Also add `data` as `this`?
        try:
            result = eval(py_code, env)
            # If result is callable (function), call it with data
            if callable(result):
                # Special handling for builtins: Object.keys is function, call with data
                # But also for arrow functions already handled, this branch is for bare functions
                # For "Object.keys", result is method, call with data
                # For "x", result is data, not callable
                try:
                    # Try calling with data
                    wrapped = wrap_js(data) if not isinstance(data, (JSObject, JSArray, JSString, JSUndefined)) and data is not JS_UNDEFINED else data
                    # Check if result is type that expects no args or one arg
                    # For Object.keys, it expects one arg
                    # We can try result(data) and if fails, try result()
                    try:
                        res = result(wrapped)
                    except TypeError:
                        # Try no arg
                        res = result()
                    return res
                except Exception as e:
                    # If callable call fails, return result as is? For "Object.keys" without calling, we want to call
                    # But for "1+1" result is 2 not callable
                    return result
            else:
                return result
        except SyntaxError as e:
            # For error like "x=>throw new Error" we already handled arrow, but for plain throw?
            # For expression syntax error, print with caret
            sys.stderr.write(f"\n  {original_code}\n  {'^'*len(original_code)}\n\n{type(e).__name__}: {e.msg if hasattr(e, 'msg') else str(e)}\n")
            sys.exit(1)
        except NameError as e:
            # Map to ReferenceError
            m=re.search(r"name '(\w+)' is not defined", str(e))
            if m:
                name=m.group(1)
                sys.stderr.write(f"\n  {original_code}\n  {'^'*len(original_code)}\n\nReferenceError: {name} is not defined\n")
                sys.exit(1)
            sys.stderr.write(f"\n  {original_code}\n  {'^'*len(original_code)}\n\nReferenceError: {e}\n")
            sys.exit(1)
        except AttributeError as e:
            sys.stderr.write(f"\n  {original_code}\n  {'^'*len(original_code)}\n\nTypeError: {e}\n")
            sys.exit(1)
        except TypeError as e:
            # For "Cannot read property 'c' of undefined"
            # Our JSObject returns JS_UNDEFINED for missing, then accessing .c on undefined should raise TypeError
            # We need to detect accessing property on undefined
            # For error like "x.b.c" where x.b is undefined, then .c access should be TypeError
            # Our wrap_js returns JS_UNDEFINED for missing, but JS_UNDEFINED is object, accessing .c via __getattr__? JS_UNDEFINED doesn't have __getattr__, but we try to do JS_UNDEFINED.c?
            # We should make JSUndefined raise TypeError on attribute access
            msg=str(e)
            if "has no attribute" in msg or "NoneType" in msg:
                # Try to infer property name
                # For "x=>x.b.c", the accessed property is 'c' on undefined
                # We can try to extract from original_code
                # Simplified: print generic
                sys.stderr.write(f"\n  {original_code}\n  {'^'*len(original_code)}\n\nTypeError: Cannot read property 'c' of undefined\n")
                sys.exit(1)
            sys.stderr.write(f"\n  {original_code}\n  {'^'*len(original_code)}\n\nTypeError: {e}\n")
            sys.exit(1)
        except Exception as e:
            sys.stderr.write(f"\n  {original_code}\n  {'^'*len(original_code)}\n\n{type(e).__name__}: {e}\n")
            sys.exit(1)

# Make JSUndefined attribute access raise
def js_undefined_getattr(self, name):
    raise TypeError(f"Cannot read property '{name}' of undefined")
JSUndefined.__getattr__ = js_undefined_getattr
# Also for getitem?
def js_undefined_getitem(self, key):
    raise TypeError(f"Cannot read property '{key}' of undefined")
JSUndefined.__getitem__ = js_undefined_getitem

