def is_primitive(v):
    return v is None or v is JS_UNDEFINED or isinstance(v, (str, JSString, int, float, bool))

def should_inline(obj, depth, parent_type, no_inline):
    if no_inline:
        return False
    if depth==0:
        return False
    if isinstance(obj, (list, JSArray)):
        if len(obj)==0:
            return True
        if all(is_primitive(el) or isinstance(el, JSString) for el in obj):
            # also check if elements are primitives (not objects/arrays)
            # For JSArray containing JSString etc., they are primitive
            # But if element is dict/list, then not primitive
            if all(not isinstance(el, (dict, list, JSObject, JSArray)) or isinstance(el, (str, JSString, int, float, bool)) or el is None or el is JS_UNDEFINED for el in obj):
                # Actually need to check each element is primitive
                # Simplify: if any element is dict/list/JSObject/JSArray, then not primitive
                has_non_primitive=False
                for el in obj:
                    if isinstance(el, (dict, list, JSObject, JSArray)):
                        has_non_primitive=True
                        break
                if not has_non_primitive:
                    return True
            # Alternative simpler: if all elements are primitive types
            all_prim=True
            for el in obj:
                if isinstance(el, (dict, JSObject, list, JSArray)):
                    all_prim=False
                    break
            return all_prim
        return False
    if isinstance(obj, (dict, JSObject)):
        if len(obj)==0:
            return True
        if parent_type=="array" and all(is_primitive(v) or isinstance(v, JSString) for v in obj.values()):
            # need to check values are primitives (not dict/list)
            all_prim=True
            for v in obj.values():
                if isinstance(v, (dict, list, JSObject, JSArray)):
                    all_prim=False
                    break
            return all_prim
        return False
    return True

def format_value(obj, indent, depth, parent_type, no_inline):
    # obj is already unwrapped? But we wrap for JS handling, but for printing we need to handle wrapped
    # For primitives, handle directly
    if obj is JS_UNDEFINED:
        return "undefined"
    if obj is None:
        return "null"
    if isinstance(obj, bool):
        return "true" if obj else "false"
    if isinstance(obj, (int, float)):
        if isinstance(obj, float):
            if math.isnan(obj):
                return "NaN"
            if math.isinf(obj):
                return "Infinity" if obj>0 else "-Infinity"
        return json.dumps(obj, ensure_ascii=False)
    if isinstance(obj, (str, JSString)):
        # For pretty printing inside JSON, need quoted
        # But if top-level string output should be raw, handled outside
        return json.dumps(str(obj), ensure_ascii=False)
    if isinstance(obj, (list, JSArray)):
        if should_inline(obj, depth, parent_type, no_inline):
            if len(obj)==0:
                return "[]"
            inner = ", ".join(format_value(el, 0, depth+1, "array", no_inline) for el in obj)
            return "[ " + inner + " ]"
        else:
            if len(obj)==0:
                return "[]"
            lines=[]
            for el in obj:
                val_str = format_value(el, indent+2, depth+1, "array", no_inline)
                lines.append(" "*(indent+2) + val_str)
            return "[\n" + ",\n".join(lines) + "\n" + " "*indent + "]"
    if isinstance(obj, (dict, JSObject)):
        if should_inline(obj, depth, parent_type, no_inline):
            if len(obj)==0:
                return "{}"
            inner = ", ".join(f'{json.dumps(k, ensure_ascii=False)}: {format_value(v, 0, depth+1, "object", no_inline)}' for k,v in obj.items())
            return "{ " + inner + " }"
        else:
            if len(obj)==0:
                return "{}"
            lines=[]
            for k,v in obj.items():
                key_str = json.dumps(k, ensure_ascii=False)
                val_str = format_value(v, indent+2, depth+1, "object", no_inline)
                lines.append(" "*(indent+2) + f'{key_str}: {val_str}')
            return "{\n" + ",\n".join(lines) + "\n" + " "*indent + "}"
    # fallback
    return json.dumps(obj, ensure_ascii=False)

def print_result(obj, no_inline):
    # obj is result after JS execution, may be JS wrapped
    # For top-level, if result is string, print raw string without quotes
    # If result is number, bool, null, undefined, print as string
    # If result is object/array, pretty print with indentation
    unwrapped = unwrap_js(obj) if isinstance(obj, (JSObject, JSArray, JSString)) else obj
    if unwrapped is JS_UNDEFINED:
        sys.stdout.write("undefined\n")
        return
    if unwrapped is None:
        sys.stdout.write("null\n")
        return
    if isinstance(unwrapped, bool):
        sys.stdout.write("true\n" if unwrapped else "false\n")
        return
    if isinstance(unwrapped, (int, float)):
        if isinstance(unwrapped, float) and (math.isnan(unwrapped) or math.isinf(unwrapped)):
            if math.isnan(unwrapped):
                sys.stdout.write("NaN\n")
            elif math.isinf(unwrapped):
                sys.stdout.write("Infinity\n" if unwrapped>0 else "-Infinity\n")
            else:
                sys.stdout.write(str(unwrapped)+"\n")
        else:
            sys.stdout.write(str(unwrapped)+"\n")
        return
    if isinstance(unwrapped, str):
        # For string result, print raw
        sys.stdout.write(unwrapped + "\n")
        return
    if isinstance(unwrapped, list):
        # Need to wrap again for pretty printing to handle JS types inside?
        # But unwrapped is plain list with possibly primitive values, we can format directly
        # Use format_value with wrapped version to handle JS types inside
        # Actually we should format the JS wrapped object, not unwrapped, to handle JSString etc.
        # So use original obj if it's JSArray/JSObject
        to_format = obj if isinstance(obj, (JSArray, JSObject, JSString)) else wrap_js(unwrapped)
        s = format_value(to_format, 0, 0, None, no_inline)
        sys.stdout.write(s+"\n")
