def remove_comments(s):
    res=""
    i=0
    in_str=False
    str_char=None
    in_single=False
    in_line_comment=False
    in_block_comment=False
    while i < len(s):
        c=s[i]
        if in_line_comment:
            if c=="\n":
                in_line_comment=False
                res+=c
            i+=1
            continue
        if in_block_comment:
            if c=="*" and i+1<len(s) and s[i+1]=="/":
                in_block_comment=False
                i+=2
                continue
            i+=1
            continue
        if in_str:
            res+=c
            if c=="\\" and i+1<len(s):
                res+=s[i+1]
                i+=2
                continue
            if c==str_char:
                in_str=False
                str_char=None
            i+=1
            continue
        if in_single:
            # Not used for JSON, but for JS? Ignore
            res+=c
            i+=1
            continue
        # not in string/comment
        if c=='"' :
            in_str=True
            str_char='"'
            res+=c
            i+=1
            continue
        if c=="'" :
            # single quote string (for JS)
            in_str=True
            str_char="'"
            res+=c
            i+=1
            continue
        if c=="/" and i+1<len(s) and s[i+1]=="/":
            in_line_comment=True
            i+=2
            continue
        if c=="/" and i+1<len(s) and s[i+1]=="*":
            in_block_comment=True
            i+=2
            continue
        res+=c
        i+=1
    return res

def find_trailing_comma(s):
    # find trailing comma outside string, returns position if found, else None
    in_str=False
    str_char=None
    for i,c in enumerate(s):
        if in_str:
            if c=="\\" and i+1<len(s):
                continue
            if c==str_char:
                in_str=False
                str_char=None
            continue
        if c=='"' or c=="'":
            in_str=True
            str_char=c
            continue
        if c==',':
            # look ahead for spaces and then } or ]
            j=i+1
            while j<len(s) and s[j] in " \t\n\r":
                j+=1
            if j<len(s) and s[j] in "}]":
                return i
    return None

