def remove_trailing_commas_outside_strings(text):
    res=""
    i=0
    in_str=False
    str_char=None
    while i < len(text):
        c=text[i]
        if in_str:
            res+=c
            if c=="\\" and i+1<len(text):
                res+=text[i+1]
                i+=2
                continue
            if c==str_char:
                in_str=False
                str_char=None
            i+=1
            continue
        if c=='"' or c=="'":
            in_str=True
            str_char=c
            res+=c
            i+=1
            continue
        if c==',':
            j=i+1
            while j<len(text) and text[j] in " \t\n\r":
                j+=1
            if j<len(text) and text[j] in "}]":
                i+=1
                continue
            res+=c
            i+=1
            continue
        res+=c
        i+=1
    return res

