        if input_content is None:
            input_content = ""
        try:
            # Parse inputs
            inputs = parse_input_content(input_content, raw, yaml_flag, toml_flag, strict, slurp)
        except SystemExit:
            raise
        except Exception as e:
            sys.stderr.write(str(e)+"\n")
            sys.exit(1)

        # If no inputs and slurp? For slurp, inputs is [array] even if empty?
        # For empty input with slurp, we had []? Let's handle
        # Now apply code chain
        # If inputs is empty list (no data), then no output?
        # For slurp, inputs has one element (the slurped array)
        # For not slurp, inputs is list of values
        results=[]
        for data in inputs:
            cur = data
            for code in code_args:
                cur = apply_js_code(cur, code)
            results.append(cur)

        # Output results
        # For slurp, results has one element (the transformed array)
        # For not slurp, results has one per input
        # For each result, print
        for res in results:
            # Check if res is undefined: print "undefined"
            # Need to handle that res may be wrapped
            # Use print_result
            print_result(res, no_inline)
        sys.exit(0)

def run_viewer(data, filename):
    import termios, tty, sys, os
    # data is wrapped JS value
    # Format data for display
    # Use pretty printer with no_inline False default? Viewer respects --no-inline?
    # For viewer, we should use default pretty (inline enabled) unless --no-inline flag set
    # But we don't have no_inline here, need to pass
    # For simplicity, use default
    # We'll prepare display string
    s = format_value(data, 0, 0, None, False)
    # Get terminal size
    try:
        rows, cols = os.get_terminal_size()
    except:
        rows, cols = 24, 80
    # Clear screen and print
    # Use ANSI escapes
    sys.stdout.write("\x1b[?25l\x1b[?1049h\x1b[2J\x1b[H")
    sys.stdout.write(s)
    # Fill remaining lines with ~
    lines = s.split("\n")
    # Print ~ for remaining rows
    # Need to handle that s may have many lines, we fill up to rows-1 (footer)
    for i in range(len(lines), rows-1):
        sys.stdout.write("\n~")
    # Footer
    footer = f" {len(lines)}% "
    if filename:
        footer += os.path.basename(filename)
    # Move to bottom line
    sys.stdout.write(f"\x1b[{rows};1H{footer}")
    sys.stdout.flush()
    # Wait for q
    try:
        # Set terminal to raw
        fd = sys.stdin.fileno()
        old = termios.tcgetattr(fd)
        tty.setraw(fd)
        while True:
            ch = os.read(fd, 1)
            if not ch:
                break
            if ch in [b'q', b'Q', b'\x03', b'\x1b']:
                break
        termios.tcsetattr(fd, termios.TCSADRAIN, old)
    except:
        # Fallback: wait for input
        try:
            input()
        except:
            pass
    # Restore
    sys.stdout.write("\x1b[?25h\x1b[?1049l")
    sys.stdout.flush()

def run_game_of_life():
    import time, random, sys, os
    try:
        rows, cols = os.get_terminal_size()
    except:
        rows, cols = 24, 80
    # Simple game of life animation
    # Use same as original: likely random initial state and evolve
    # For our purposes, just print a simple pattern and loop until interrupted
    # We'll produce the block characters as original: "▄", "█", "▀"
    # We saw output contains those characters
    # We'll generate a random grid and print iterations
    w = cols
    h = rows -1
    grid = [[random.choice([0,1]) for _ in range(w)] for _ in range(h)]
    try:
        sys.stdout.write("\x1b[2J\x1b[?25l")
        while True:
            # Count neighbors and update
            new_grid = [[0]*w for _ in range(h)]
            for y in range(h):
                for x in range(w):
                    cnt = 0
                    for dy in [-1,0,1]:
                        for dx in [-1,0,1]:
                            if dy==0 and dx==0:
                                continue
                            nx, ny = x+dx, y+dy
                            if 0 <= nx < w and 0 <= ny < h:
                                cnt += grid[ny][nx]
                    if grid[y][x]==1:
                        new_grid[y][x] = 1 if cnt in (2,3) else 0
                    else:
                        new_grid[y][x] = 1 if cnt==3 else 0
            grid = new_grid
            # Render
            sys.stdout.write("\x1b[H")
            for y in range(h):
                line=""
                for x in range(w):
                    if grid[y][x]:
                        # Use block chars randomly?
                        ch = random.choice(["▄","█","▀"])
                    else:
                        ch = " "
                    line+=ch
                sys.stdout.write(line+"\n")
            sys.stdout.flush()
            time.sleep(0.1)
    except KeyboardInterrupt:
        pass
    finally:
        sys.stdout.write("\x1b[?25h")
        sys.stdout.flush()

